export function StopSlotReel(reelIndex: any): any {
  gTasks[sSlotMachine.slotReelTasks[reelIndex]].tState = REEL_TASK_DECIDE_STOP;
}

/** static bool8 IsSlotReelMoving(u8 reelIndex) */
