/** static void LoadPikaPowerMeter(u8 bolts) */
export function LoadPikaPowerMeter(bolts: any): any {
  let i: any = null;
      let r3: any = 0, r1 = 0;
      let r4: any = 3;
      for (i = 0; i < bolts; i++, r4++)
      {
          r3 = 0, r1 = 0;
          if (i == 0)
              r3 = 1, r1 = 1;
          else if (i == 15)  
              r3 = 2, r1 = 2;
          sSelectedPikaPowerTile[r1] = sPikaPowerTileTable[r3][0];
          LoadBgTilemap(2,sSelectedPikaPowerTile[r1], 2, r4 + _0x40);
      }
      for (; i < 16; i++, r4++)
      {
          r3 = 0, r1 = 3;
          if (i == 0)
              r3 = 1, r1 = 1;
          else if (i == 15)
              r3 = 2, r1 = 2;
          sSelectedPikaPowerTile[r1] = sPikaPowerTileTable[r3][1];
          LoadBgTilemap(2,sSelectedPikaPowerTile[r1], 2, r4 + _0x40);
      }
      gTasks[sSlotMachine.pikaPowerBoltTaskId].data[1] = bolts;
}

