/** static void ReelTime_PikachuSpeedUp1(struct Task *task) */
export function ReelTime_PikachuSpeedUp1(task: any): any {
  let i: any = null;
      const pikachuAnimIds: any[] = [];
      const reelTimeBoltDelays: any[] = [];
      const pikachuAuraFlashDelays: any[] = [];

      memcpy(pikachuAnimIds, sReelTimePikachuAnimIds, 0);
      memcpy(reelTimeBoltDelays, sReelTimeBoltDelays, 0);
      memcpy(pikachuAuraFlashDelays, sPikachuAuraFlashDelays, 0);

      AdvanceReeltimeReel(task.tRtReelSpeed >> 8);
       
      task.tRtReelSpeed -= 4;
      i = 4 - (task.tRtReelSpeed >> 8);
      SetReelTimeBoltDelay(reelTimeBoltDelays[i]);
      SetReelTimePikachuAuraFlashDelay(pikachuAuraFlashDelays[i]);
      StartSpriteAnimIfDifferent(gSprites[sSlotMachine.reelTimePikachuSpriteId], pikachuAnimIds[i]);
       
      if (task.tRtReelSpeed <= _0x100)
      {
          task.tState++;  
          task.tRtReelSpeed = _0x100;
          task.tTimer1 = 0;
      }
}

