/** static void SpriteCB_CoinNumber(struct Sprite *sprite) */
export function SpriteCB_CoinNumber(sprite: any): any {
  let tag: any = sSlotMachine.coins;
      if (sprite.sIsPayout)
          tag = sSlotMachine.payout;
      if (sprite.sCurNum != tag)
      {
           
          sprite.sCurNum = tag;
          tag %= sprite.sDigitMax;
          tag /= sprite.sDigitMin;

          tag += GFXTAG_NUM_0;
          sprite.sheetTileStart = GetSpriteTileStartByTag(tag);
          SetSpriteSheetFrameTileNum(sprite);
      }
}

