/** static void SpriteCB_DigitalDisplay_Reel(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_Reel(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          sprite.x += 4;
          if (sprite.x >= DISPLAY_WIDTH - 32)
          {
              sprite.x = DISPLAY_WIDTH - 32;
              sprite.sState++;
          }
          break;
      case 1:
          if (++sprite.sCounter > 90)
              sprite.sState++;
          break;
      case 2:
          sprite.x += 4;
          if (sprite.x >= DISPLAY_WIDTH + 32)
              sprite.sState++;
          break;
      case 3:
          sprite.sWaitForAnim = FALSE;
          break;
      }
}

/** static void SpriteCB_DigitalDisplay_Time(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_Time(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          sprite.x -= 4;
          if (sprite.x <= DISPLAY_WIDTH - 32)
          {
              sprite.x = DISPLAY_WIDTH - 32;
              sprite.sState++;
          }
          break;
      case 1:
          if (++sprite.sCounter > 90)
              sprite.sState++;
          break;
      case 2:
          sprite.x -= 4;
          if (sprite.x <= 144)
              sprite.sState++;
          break;
      case 3:
          sprite.sWaitForAnim = FALSE;
          break;
      }
}

/** static void SpriteCB_DigitalDisplay_ReelTimeNumber(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_ReelTimeNumber(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          StartSpriteAnim(sprite, sSlotMachine.reelTimeSpinsLeft - 1);
          sprite.sState++;
           
      case 1:
          if (++sprite.sCounter >= 4)
          {
              sprite.sState++;
              sprite.sCounter = 0;
          }
          break;
      case 2:
          sprite.x += 4;
          if (sprite.x >= DISPLAY_WIDTH - 32)
          {
              sprite.x = DISPLAY_WIDTH - 32;
              sprite.sState++;
          }
          break;
      case 3:
          if (++sprite.sCounter > 90)
              sprite.sState++;
          break;
      case 4:
          sprite.x += 4;
          if (sprite.x >= DISPLAY_WIDTH + 8)
              sprite.sState++;
          break;
      case 5:
          sprite.sWaitForAnim = FALSE;
          break;
      }
}

/** static void SpriteCB_DigitalDisplay_PokeballRocking(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_PokeballRocking(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          sprite.animPaused = TRUE;
          sprite.sState++;
           
      case 1:
          sprite.y += 8;
          if (sprite.y >= _0x70)
          {
              sprite.y = _0x70;
              sprite.sCounter = 16;
              sprite.sState++;
          }
          break;
      case 2:
          if (sprite.data[2] == 0)
          {
              sprite.y -= sprite.sCounter;
              sprite.sCounter = -sprite.sCounter;
              if (++sprite.data[3] >= 2)
              {
                  sprite.sCounter >>= 2;
                  sprite.data[3] = 0;
                  if (sprite.sCounter == 0)
                  {
                      sprite.sState++;
                      sprite.sWaitForAnim = FALSE;
                      sprite.animPaused = FALSE;
                  }
              }
          }
          sprite.data[2]++;
          sprite.data[2] &= _0x07;
          break;
      }
}

/** static void SpriteCB_DigitalDisplay_Stop(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_Stop(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          if (++sprite.sCounter > 8)
              sprite.sState++;
          break;
      case 1:
          sprite.y += 2;
          if (sprite.y >= _0x30)
          {
              sprite.y = _0x30;
              sprite.sState++;
              sprite.sWaitForAnim = FALSE;
          }
          break;
      }
}

/** static void SpriteCB_DigitalDisplay_AButtonStop(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_AButtonStop(sprite: any): any {
  switch (sprite.sState)
      {
      case 0:
          sprite.invisible = TRUE;
          if (++sprite.sCounter > _0x20)
          {
              sprite.sState++;
              sprite.sCounter = 5;
              sprite.oam.mosaic = TRUE;
              sprite.invisible = FALSE;
              StartSpriteAnim(sprite, 1);
              SetGpuReg(REG_OFFSET_MOSAIC, ((sprite.sCounter << 4) | sprite.sCounter) << 8);
          }
          break;
      case 1:
          sprite.sCounter -= (sprite.data[2] >> 8);
          if (sprite.sCounter < 0)
              sprite.sCounter = 0;
          SetGpuReg(REG_OFFSET_MOSAIC, ((sprite.sCounter << 4) | sprite.sCounter) << 8);
          sprite.data[2] &= 0xff;
          sprite.data[2] += _0x80;
          if (sprite.sCounter == 0)
          {
              sprite.sState++;
              sprite.sWaitForAnim = FALSE;
              sprite.oam.mosaic = FALSE;
              StartSpriteAnim(sprite, 0);
          }
          break;
      }
}

/** static void SpriteCB_DigitalDisplay_PokeballShining(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_PokeballShining(sprite: any): any {
  if (sprite.sCounter < 3)
      {
          LoadPalette(sPokeballShiningPalTable[sprite.sCounter], OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_DIG_DISPLAY)), PLTT_SIZE_4BPP);
          if (++sprite.data[2] >= 4)
          {
              sprite.data[1]++;
              sprite.data[2] = 0;
          }
      }
      else
      {
          LoadPalette(sPokeballShiningPalTable[sprite.sCounter], OBJ_PLTT_ID(IndexOfSpritePaletteTag(PALTAG_DIG_DISPLAY)), PLTT_SIZE_4BPP);
          if (++sprite.data[2] >= 25)
          {
              sprite.sCounter = 0;
              sprite.data[2] = 0;
          }
      }
      StartSpriteAnimIfDifferent(sprite, 1);
      sprite.sWaitForAnim = FALSE;
}

/** static void SpriteCB_DigitalDisplay_RegBonus(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_RegBonus(sprite: any): any {
  const letterXOffset: any = [  0, -40,   0,   0, 48,   0,  24,   0];
      const letterYOffset: any = [-32,   0, -32, -48,  0, -48,   0, -48];
      const letterDelay: any = [ 16,  12,  16,   0,  0,   4,   8,   8];

      switch (sprite.sState)
      {
      case 0:
          sprite.x2 = letterXOffset[sprite.sSpriteId];
          sprite.y2 = letterYOffset[sprite.sSpriteId];
          sprite.sCounter = letterDelay[sprite.sSpriteId];
          sprite.sState++;
           
      case 1:
          if (sprite.sCounter-- == 0)
              sprite.sState++;
          break;
      case 2:
          if (sprite.x2 > 0)
              sprite.x2 -= 4;
          else if (sprite.x2 < 0)
              sprite.x2 += 4;

          if (sprite.y2 > 0)
              sprite.y2 -= 4;
          else if (sprite.y2 < 0)
              sprite.y2 += 4;

          if (sprite.x2 == 0 && sprite.y2 == 0)
              sprite.sState++;
          break;
      }
}

/** static void SpriteCB_DigitalDisplay_BigBonus(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_BigBonus(sprite: any): any {
  const sp0: any = [160, 192, 224, 104, 80, 64, 48, 24];

      if (sprite.sState == 0)
      {
          sprite.sState++;
          sprite.sCounter = 12;
      }
      sprite.x2 = Cos(sp0[sprite.sSpriteId], sprite.sCounter);
      sprite.y2 = Sin(sp0[sprite.sSpriteId], sprite.sCounter);
      if (sprite.sCounter != 0)
          sprite.sCounter--;
}

/** static void SpriteCB_DigitalDisplay_AButtonStart(struct Sprite *sprite) */
export function SpriteCB_DigitalDisplay_AButtonStart(sprite: any): any {
  switch (sprite.sState)
      {
          case 0:
              sSlotMachine.winIn = WININ_WIN0_BG_ALL | WININ_WIN0_CLR;
              sSlotMachine.winOut = WINOUT_WIN01_BG_ALL | WINOUT_WIN01_OBJ | WINOUT_WIN01_CLR;
              sSlotMachine.win0v = WIN_RANGE(32, 136);
              sprite.invisible = TRUE;
              sprite.sState++;
               
          case 1:
              sprite.sCounter += 2;
              sprite.data[2] = sprite.sCounter + 176;
              sprite.data[3] = DISPLAY_WIDTH - sprite.sCounter;
              if (sprite.data[2] > 208)
                  sprite.data[2] = 208;
              if (sprite.data[3] < 208)
                  sprite.data[3] = 208;
              sSlotMachine.win0h = (sprite.data[2] << 8) | sprite.data[3];
              if (sprite.sCounter > 51)
              {
                  sprite.sState++;
                  sSlotMachine.winIn = WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR;
              }
              break;
          case 2:
              if (sSlotMachine.bet == 0)
                  break;
              AddDigitalDisplaySprite(DIG_SPRITE_A_BUTTON, SpriteCallbackDummy, 208, 116, 0);
              sSlotMachine.win0h = WIN_RANGE(192, 224);
              sSlotMachine.win0v = WIN_RANGE(104, 128);
              sSlotMachine.winIn = WININ_WIN0_BG_ALL | WININ_WIN0_CLR;
              sprite.sState++;
              sprite.sCounter = 0;
               
          case 3:
              sprite.sCounter += 2;
              sprite.data[2] = sprite.sCounter + 192;
              sprite.data[3] = DISPLAY_WIDTH - 16 - sprite.sCounter;
              if (sprite.data[2] > 208)
                  sprite.data[2] = 208;
              if (sprite.data[3] < 208)
                  sprite.data[3] = 208;
              sSlotMachine.win0h = (sprite.data[2] << 8) | sprite.data[3];
              if (sprite.sCounter > 15)
              {
                  sprite.sState++;
                  sSlotMachine.winIn = WININ_WIN0_BG_ALL | WININ_WIN0_OBJ | WININ_WIN0_CLR;
              }
              break;
      }
}

